import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        byte[] s = System.in.readAllBytes();
        boolean[] seen = new boolean[26];
        int count = 0;
        for (byte c : s) {
            if (c >= 'A' && c <= 'Z') break; // only the prefix before the first uppercase letter counts
            if (c >= 'a' && c <= 'z' && !seen[c - 'a']) {
                seen[c - 'a'] = true;
                count++;
            }
        }
        System.out.println(count);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

func main() {
	s, _ := io.ReadAll(os.Stdin)
	var seen [26]bool
	count := 0
	for _, c := range s {
		if c >= 'A' && c <= 'Z' {
			break // only the prefix before the first uppercase letter counts
		}
		if c >= 'a' && c <= 'z' && !seen[c-'a'] {
			seen[c-'a'] = true
			count++
		}
	}
	fmt.Println(count)
}
